import { defineRailway, github, preserve, project, service } from "railway/iac";

// Infrastructure as Code for the Railway project, replacing the deprecated
// Config-as-Code railway.json (Railway stops honouring it after 2026-12-01).
// Generated by `railway config pull` on 2026-11-14, then hand-corrected:
//   - `pull` renders the GitHub source and the poller service under the same
//     identifier, which doesn't compile; the source is `repo` here.
//   - `pull` cannot see railway.json, so it omitted the poller's start command
//     and restart policy. Without them the poller would have no start command
//     once railway.json stops being read -- they are set explicitly below.
// Secrets are preserve(): Railway keeps the existing values, nothing sensitive
// is written to this file. collect-cycle's variables are cross-service
// references to the poller's; preserve() leaves them exactly as they are.
export default defineRailway(() => {
  const repo = github("natanimxo/crypto-content-bot", { checkSuites: false });

  // Always-on Telegram approval poller (long-polls getUpdates; only one
  // instance may run per bot token, hence replicas 1).
  const poller = service("crypto-content-bot", {
    source: repo,
    start: "python scripts/poller_daemon.py",
    replicas: { "sfo": 1 },
    deploy: { restartPolicyType: "ALWAYS" },
    env: { DATABASE_URL: preserve(), DEEPSEEK_API_KEY: preserve(), ETHERSCAN_API_KEY: preserve(), TELEGRAM_ALLOWED_USER_IDS: preserve(), TELEGRAM_BOT_TOKEN: preserve(), TELEGRAM_OPERATOR_CHAT_ID: preserve() },
  });

  // Cron service: one collect -> score -> notify pass every 4h, then exit.
  const collectCycle = service("collect-cycle", {
    source: repo,
    start: "python scripts/collect_cycle.py",
    replicas: { "sfo": 1 },
    deploy: { cronSchedule: "0 */4 * * *", restartPolicyType: "NEVER" },
    env: { DATABASE_URL: preserve(), DEEPSEEK_API_KEY: preserve(), ETHERSCAN_API_KEY: preserve(), TELEGRAM_ALLOWED_USER_IDS: preserve(), TELEGRAM_BOT_TOKEN: preserve(), TELEGRAM_OPERATOR_CHAT_ID: preserve() },
  });

  // 2-hour earning_opportunities cycle (Phase 5, 2026-11-15, operator direction): collect -> score -> notify Earn Stack only, then
  // exit. A separate service because the main cycle's notify visits every channel and its pacing assumes 4 hours. Cron at :30 so it
  // never overlaps the :00 main cycle. The operator created the service (and set the schedule through a preset); the schedule is
  // defined HERE and `railway config apply` is authoritative. Secrets are preserve(): Railway keeps the existing values.
  const collectEarning = service("collect-earning", {
    source: repo,
    start: "python scripts/collect_earning.py",
    replicas: { "sfo": 1 },
    deploy: { cronSchedule: "30 */2 * * *", restartPolicyType: "NEVER" },
    env: { DATABASE_URL: preserve(), DEEPSEEK_API_KEY: preserve(), TELEGRAM_ALLOWED_USER_IDS: preserve(), TELEGRAM_BOT_TOKEN: preserve(), TELEGRAM_OPERATOR_CHAT_ID: preserve() },
  });

  return project("fortunate-success", {
    resources: [poller, collectCycle, collectEarning],
  });
});
